WITH p AS (
  SELECT $__timeFrom()::timestamptz AS t0, $__timeTo()::timestamptz AS t1, ($__interval_ms * interval '1 millisecond') AS iv
), b AS (
  SELECT generate_series(p.t0, p.t1, p.iv) AS t FROM p
), ev AS (
  SELECT bin, sum(qd) AS qd, sum(rd) AS rd FROM (
    SELECT date_bin(p.iv, j.created_at, p.t0) AS bin, 1 AS qd, 0 AS rd FROM jobs j, p WHERE j.created_at >= p.t0
    UNION ALL
    SELECT date_bin(p.iv, j.started_at, p.t0), -1, 1 FROM jobs j, p WHERE j.started_at >= p.t0
    UNION ALL
    SELECT date_bin(p.iv, j.finished_at, p.t0), CASE WHEN j.started_at IS NULL THEN -1 ELSE 0 END, CASE WHEN j.started_at IS NULL THEN 0 ELSE -1 END FROM jobs j, p WHERE j.finished_at >= p.t0
  ) x GROUP BY 1
), base AS (
  SELECT count(*) FILTER (WHERE j.started_at IS NULL OR j.started_at >= p.t0) AS q, count(*) FILTER (WHERE j.started_at < p.t0) AS r FROM jobs j, p WHERE j.created_at < p.t0 AND (j.finished_at IS NULL OR j.finished_at >= p.t0)
)
SELECT b.t AS time, base.q + coalesce(sum(ev.qd) OVER (ORDER BY b.t), 0) AS queued, base.r + coalesce(sum(ev.rd) OVER (ORDER BY b.t), 0) AS running FROM b CROSS JOIN base LEFT JOIN ev ON ev.bin = b.t ORDER BY 1

WITH p AS (
  SELECT $__timeFrom()::timestamptz AS t0, $__timeTo()::timestamptz AS t1, ($__interval_ms * interval '1 millisecond') AS iv
), b AS (
  SELECT generate_series(p.t0, p.t1, p.iv) AS t FROM p
), ev AS (
  SELECT date_bin(p.iv, m.updated_at, p.t0) AS bin, count(*) AS n FROM media_item m, p WHERE m.analysis_status = 'failed' AND m.deleted = false AND m.updated_at >= p.t0 GROUP BY 1
), base AS (
  SELECT count(*) AS n FROM media_item m, p WHERE m.analysis_status = 'failed' AND m.deleted = false AND m.updated_at < p.t0
)
SELECT b.t AS time, base.n + coalesce(sum(ev.n) OVER (ORDER BY b.t), 0) AS failed_analysis FROM b CROSS JOIN base LEFT JOIN ev ON ev.bin = b.t ORDER BY 1

